-- 009: step text no longer references step numbers (numbers renumber when a variant hides steps)
update guides set content = $j${"id": "sway-front", "title": "Front sway bar upgrade", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 8P · Mk6 GTI/Golf (same PQ35 front subframe)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "How far do you want to take it apart?", "hint": "The bar hides behind the subframe, so the subframe has to come down either way. Owners mostly lower it a few inches and unbolt the steering rack from it. Manufacturer instructions drop it further and also disconnect the steering column, ball joints and tie rods.", "options": [{"id": "partial", "label": "Partial lower (owner method)", "when": "Fewer parts touched, tighter to work in. Recommended for a driveway."}, {"id": "full", "label": "Full drop (manufacturer method)", "when": "More room, more disconnecting, steering-column care needed. Best on a lift."}]}, "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr with a lift and a helper", "difficulty": 4, "cost": "$250–450 + alignment", "risk": "Subframe on a jack · single-use stretch bolts · alignment afterwards", "why": "The rear bar changed the car's balance. The front bar is about grip: less roll means the outside front tire stays flatter on the road, so a strut car like this one stops giving away camber mid-corner.", "note": "One vendor calls this 'easy'. Every owner account says three hours, two people, and an alignment. Believe the owners."}, "heroCap": "The bar sits in the channel between the subframe and the steering rack. There is no way to get it out without lowering the subframe.", "lifespan": {"title": "When owners do this", "headline": ["Usually after the rear bar and tires, before or with coilovers"], "earliest": null, "detail": "The stock bar doesn't wear out. Owners add a front bar when they've already done the rear and want the front to stop washing out, or as part of a bigger suspension job while the subframe is already down.", "factors": ["Rear bar already installed", "Coilovers or lowering springs going in", "Track days"], "inspect": ["While the subframe is down: dogbone (pendulum) mount bushing and front control-arm bushings are worth a look"], "confidence": {"level": "community", "n": 5, "note": "Forum consensus on ordering. Which bar is a preference."}}, "should": {"yesIf": ["You've done the rear bar and the front still pushes wide", "You want flatter cornering without harsher ride", "You're already dropping the subframe for something else", "You have a torque wrench that does angle, or a patient helper and a marker"], "codes": [], "notes": ["A stiffer front bar on a front-driver sounds like it should add understeer. In practice it reduces body roll, which keeps the loaded front tire upright, so it usually adds front grip rather than taking it away. Rear bar first, then front, is the order almost everyone lands on.", "This is the most involved job in the app so far. Nothing is dangerous once the car is on stands, but a subframe on a floor jack wants a second person, and the alignment afterwards is not optional."], "confidence": {"level": "high", "n": 6, "note": "Method and rationale agree across the manufacturer guide, four forum DIYs, and a magazine test."}}, "parts": [{"tier": "aftermarket", "name": "Front sway bar kit (bar, poly bushings, brackets, grease)", "pn": "see options below", "note": "Most kits include the stretch bolts you need; check yours", "price": "$250–400", "links": []}, {"tier": "oe", "name": "Subframe & control-arm bolts, M12 (×6)", "pn": "single-use", "note": "Stretch bolts. Every source says replace", "price": "$30–50", "links": []}, {"tier": "oe", "name": "Steering rack bolts, M10 (×4)", "pn": "single-use", "note": "Also stretch bolts", "price": "$15", "links": []}, {"tier": "oe", "name": "Pendulum (dogbone) mount bolts", "pn": "single-use", "note": "Two into the transmission", "price": "$10", "links": []}, {"tier": "oe", "name": "End-link nuts (×2)", "pn": "self-locking", "note": "Replace whenever removed", "price": "$4", "links": []}, {"tier": "oe", "name": "Steering shaft u-joint bolt", "pn": "single-use", "note": "Full-drop method only", "price": "$5", "links": [], "only": ["full"]}], "aftermarket": [{"name": "ECS Tuning 26mm", "note": "Solid, non-adjustable, comes with poly bushings, all stretch bolts and subframe spacer plates. The install PDF is the most complete one available.", "price": "$300", "signal": "Best documented", "links": [{"store": "ECS Tuning install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_9205_Volkswagen_MK5-MK6_ECS_Front_Sway_Bar_Installation.pdf"}]}, {"name": "H&R 26mm", "note": "Tubular, non-adjustable, rubber-lined bushings that need no greasing. The bar the 2008 owner DIYs were written around.", "price": "$250–300", "signal": "Forum favorite", "links": []}, {"name": "034Motorsport adjustable", "note": "Two-hole adjustable, billet brackets. Grassroots Motorsports ran it on the soft setting and set a personal best.", "price": "$350–450", "signal": "Track-leaning pick", "links": []}, {"name": "APR / Hotchkis", "note": "Same bar under two names. Instructions insisted on load on the wheels throughout; owners found that only matters for the end links.", "price": "$300–350", "signal": "Fine, with that caveat", "links": []}], "tools": [{"name": "Floor jack + two stands, plus a second jack (or transmission jack) for the subframe", "note": "A board on the jack pad spreads the load"}, {"name": "Sockets: 13, 16, 17, 18, 21mm · ½\" breaker bar", "note": "The 21mm subframe bolts are very tight"}, {"name": "6mm triple-square or 5mm hex (end links) · T20/T25 Torx (belly pan)"}, {"name": "Torque wrench that reads to 120 Nm, and an angle gauge (or a marker for the +90° turns)"}, {"name": "Pry bar, penetrating oil, wire brush, marker or paint pen for reference marks"}, {"name": "Angle grinder (optional)", "note": "Owners cut the hollow stock bar in two rather than wrestle it out", "only": ["partial"]}], "before": ["Level ground. Stands on the body jack points, never under the subframe you're about to drop.", "Raise both sides of the front together; one side up puts the bar under load.", "Mark the subframe's position on the body with a paint pen before a single bolt comes out. Its outline (the 'footprint') is your only alignment reference.", "Book an alignment for afterwards. Subframe position sets toe and camber; you will not get it back exactly by eye.", "Full-drop method: park with the steering wheel dead straight and keep it there. Rotating the wheel with the column disconnected can damage the airbag clockspring."], "steps": [{"n": 1, "title": "Steering shaft (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Inside the car, remove the two 13mm fasteners on the steering-shaft cover at the pedals and lift it off. Remove the u-joint bolt where the shaft meets the rack and slide the joint up off the rack. It's a single-use bolt."}, {"t": "warn", "b": "From this point until the joint is back on, nobody turns the steering wheel. A rotated clockspring is an airbag light at best."}]}, {"n": 2, "title": "Raise the front, wheels off, belly pan off", "blocks": [{"t": "text", "b": "Loosen the lug bolts (17mm) on the ground, raise both sides, stands under the body. Wheels off. Remove the plastic belly pan or insulation tray (T20/T25) so you can see the subframe."}]}, {"n": 3, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "18mm nut on each link at the bar. If the stud spins, hold it with a 6mm triple-square (some links: 5mm hex) and turn the nut. They're often seized: wire-brush the exposed thread, soak with penetrating oil, and work the nut back and forth. Don't heat them; the joint boot won't survive it."}, {"t": "ill", "id": "fsb-endlink", "cap": "Stud held, nut turned. Same technique front and rear."}]}, {"n": 4, "title": "Headlight level sensor (if you have HIDs)", "blocks": [{"t": "text", "b": "Driver's side, above the lower control arm: unplug the sensor and unbolt its arm bracket from the arm (10mm). Note which way the joint points so it goes back the same."}]}, {"n": 5, "title": "Ball joints and tie rods (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Remove the three 16mm ball-joint nuts each side and pull the control arm down off the joint; a pry bar between them if they're corroded together. Remove both outer tie-rod nuts (18mm) and pop the tie rods out of the bearing housings with a separator, or a sharp hammer blow to the housing."}]}, {"n": 6, "title": "Unbolt everything hanging on the subframe", "blocks": [{"t": "text", "b": "Two exhaust hanger bolts at the rear of the subframe (13mm). The four steering-rack bolts (13mm), two per side, where the rack sits on the subframe. The four sway-bar bracket bolts (13mm)."}, {"t": "text", "b": "Pendulum (dogbone) mount: two bolts into the transmission (16mm) and, on the partial method, the two into the subframe (13mm) so the mount comes free.", "only": ["partial"]}, {"t": "text", "b": "Pendulum mount: remove the two bolts into the transmission (16mm).", "only": ["full"]}]}, {"n": 7, "title": "Jack under the subframe, then the big bolts", "caution": true, "blocks": [{"t": "text", "b": "Second jack (with a board) snug under the middle of the subframe. Now the six 18mm/21mm subframe and control-arm bolts: two long ones at the rear, two at the rear control-arm brackets, two forward ones hidden behind the control arms (socket on a 6-inch extension). Loosen the forward pair first; remove them last."}, {"t": "warn", "b": "The subframe is heavy and the jack is the only thing holding it. Have your helper steady it from here on. Never put any part of you under it."}, {"t": "torque", "label": "Subframe & control-arm bolts (M12, on reassembly)", "nm": 70, "c": {"level": "varies", "n": 2, "note": "Manufacturer: 70 Nm + 90°. Owner table: 70 Nm (52 lb-ft) + 45°. Same base value; the angle differs. We show the manufacturer's."}, "note": "+90° turn"}]}, {"n": 8, "title": "Lower the subframe", "blocks": [{"t": "text", "b": "Lower the jack slowly and evenly, about four inches, watching the steering rack: it needs to lift off its dowel pins and come free of the subframe. A screwdriver under the rack helps release the pins. The rack stays connected to the column and just hangs.", "only": ["partial"]}, {"t": "text", "b": "Lower the jack a little at a time. As soon as you can reach it, remove the hidden 10mm bolt holding the steering-rack wiring harness to the rack (driver's side, inside the subframe) and release the harness clip a few inches along. Then lower until the bar is fully exposed, and lift the rack slightly rearward off its dowel pins.", "only": ["full"]}, {"t": "ill", "id": "fsb-drop", "cap": "Subframe on the jack, lowered. The bar comes out over the passenger side of the subframe, forward and down, while the driver's end threads between the subframe and rack."}]}, {"n": 9, "title": "Get the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Lift the bar up and over the passenger-side subframe arm, bring it forward and down, and guide the driver's end between the subframe and the rack. Two people, some swearing, several attempts. The bushings snag on the rack; snapping the old brackets off the bar first helps."}, {"t": "note", "b": "Owner shortcut: with the bar still bolted in, cut it in half with a grinder. The stock bar is hollow and goes quickly. Eye protection; you're on your back under sparks. Then each half comes out easily.", "only": ["partial"]}]}, {"n": 10, "title": "Bushings and brackets onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of poly bushings with the kit's grease (never petroleum grease; never any grease on factory rubber bushings). Slide them on against the stops. Lower brackets under, uppers on top, raised face up, bolt holes outboard. Some kits fit the brackets loosely at this point; others want them fully seated. Follow the kit sheet."}]}, {"n": 11, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of removal: driver's end between rack and subframe first, then lift the passenger end over. Set the bar in front of the rack. Adjust the rack's position as needed so the bar drops into place."}]}, {"n": 12, "title": "Raise the subframe and start every bolt by hand", "caution": true, "blocks": [{"t": "text", "b": "Raise the jack until the subframe meets the body. Seat the steering rack onto its dowel pins first; if it isn't fully seated you'll end up with a loose rack. Then start, by hand and loosely, in this order: rear control-arm bolts, the four rack bolts, the four sway-bar bracket bolts, forward subframe bolts, then the two long rear subframe bolts. Full-drop: reconnect the harness clip and its 10mm bolt as the subframe comes up.", "only": ["partial", "full"]}, {"t": "text", "b": "Kits that supply subframe spacer plates: they go between the subframe and body at the rear mounts. Fit them whether or not the car had them.", "only": ["partial", "full"]}, {"t": "text", "b": "Now align. Nudge the subframe until every bolt hole lines up with your paint marks and the footprint. Loosen the 'horns' and rear brackets if it won't move; snug bolts fight you. Only when everything lines up do you tighten anything."}, {"t": "warn", "b": "Tighten nothing to torque until all fourteen bolts are started and the subframe is on its marks. One bolt torqued early locks the subframe in the wrong place and you'll be doing this again after the alignment shop calls."}, {"t": "torque", "label": "Steering rack bolts (M10)", "nm": 50, "c": {"level": "varies", "n": 2, "note": "Manufacturer 50 Nm + 90°; owner table 37 lb-ft + 45°. Same base value."}, "note": "+90° turn"}, {"t": "torque", "label": "Sway bar bracket bolts (M8)", "nm": 20, "c": {"level": "varies", "n": 2, "note": "Manufacturer 20 Nm + 90°; owner table 15 lb-ft + 45°."}, "note": "+90° turn"}, {"t": "torque", "label": "Pendulum mount bolts", "nm": 40, "alt": [50], "c": {"level": "medium", "n": 2, "note": "40 Nm for 8.8-grade bolts, 50 Nm for 10.9-grade, each + 90°. Check the number stamped on the bolt head."}, "note": "+90° turn"}, {"t": "ill", "id": "fsb-bolts", "cap": "Order matters: seat the rack, start everything loose, align to your marks, then torque. Subframe and arm bolts get their angle last."}]}, {"n": 13, "title": "Reconnect the rest", "blocks": [{"t": "text", "b": "Exhaust hanger back on the subframe. Ball joints: three nuts each side, 60 Nm for a cast arm or 100 Nm for an aluminium/sheet-steel arm. Tie rods: 20 Nm + 90°. Level sensor arm and plug.", "only": ["full"]}, {"t": "text", "b": "Exhaust hanger back on the subframe. Level sensor arm and plug.", "only": ["partial"]}, {"t": "text", "b": "Steering shaft: seat the u-joint back on the rack and torque the new bolt to 30 Nm. Only now may the wheel turn.", "only": ["full"]}]}, {"n": 14, "title": "End links, on the ground", "blocks": [{"t": "text", "b": "Pass the studs through the bar's holes (adjustable bars: start on the softer, outer hole), start new self-locking nuts. Wheels on, torque to 120 Nm, lower the car. Then torque the end-link nuts with the car on its wheels so the links aren't preloaded."}, {"t": "torque", "label": "End-link nuts (M10)", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft agrees across the manufacturer guide, an MQB guide and a forum torque thread."}}]}, {"n": 15, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Drive gently to the alignment shop. Tell them the subframe was lowered. After 50 miles, re-check the end links and that nothing clunks over one-wheel bumps."}]}], "alsoReplace": [{"name": "Pendulum (dogbone) mount insert or bushing", "why": "It's unbolted anyway, and a tired one is the usual source of drivetrain clunk on these cars. A poly insert is $30 and ten minutes here versus an hour on its own."}, {"name": "Front sway-bar end links", "why": "They're off. If the boots are cracked or the joints have play, new ones now save a second trip under the car."}, {"name": "Subframe alignment (Deadset-style) kit", "why": "Replaces the subframe's slop with locating sleeves so it can't shift under load. Only sensible while the bolts are already out."}], "check": {"tab": "Pick a setting", "title": "Which hole, if your bar is adjustable?", "illId": "setting", "illCap": "Same logic as the rear bar: the hole closer to the pivot is stiffer.", "rows": [{"see": "Street car, all-season or touring tires", "means": "You want the roll reduction without changing balance much.", "do": "Softer (outer) hole. Most stay here."}, {"see": "Summer tires, already on the stiff rear setting", "means": "The car may have gone tail-happy; the front bar brings balance back.", "do": "Softer hole first, evaluate, then stiffer if the front still rolls more than the rear."}, {"see": "Track use", "means": "You'll tune front and rear together per event.", "do": "Stiffer hole, adjustable end links front and rear."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus one magazine test (fastest lap on the soft setting)."}}, "aftercare": ["Alignment within the first drive or two. Not optional.", "Re-torque end links after 50 miles.", "Poly bushings squeak when dry; re-grease at the first squeak.", "Clunk from the front on take-off after this job: check the pendulum mount bolts."], "disagreements": [{"topic": "Full drop or partial lower?", "pos": "Manufacturer disconnects steering column, ball joints and tie rods and drops the subframe fully; owners lower it about four inches and unbolt the rack.", "call": "Both work. Partial for a driveway, full on a lift. You choose at the top of the guide."}, {"topic": "+45° or +90° on the stretch bolts?", "pos": "Manufacturer PDF says +90°; the 2008 owner table says +45° on the same base values.", "call": "Manufacturer, since it's current and cites the bolt sizes. The base torque agrees everywhere."}, {"topic": "How hard is it?", "pos": "'Skill Level 1 – Easy' vs. every owner account.", "call": "4 out of 5. Plan a full afternoon and a helper."}, {"topic": "Load on the wheels during install?", "pos": "APR's sheet said keep the car loaded throughout; owners found the subframe wouldn't align that way.", "call": "Unloaded for the subframe and rack; loaded only for the final end-link torque."}], "sources": ["ECS Tuning Mk5/Mk6 Front Sway Bar installation PDF (2019)", "VWVortex 'DIY: Front Sway Bar Install' (2008)", "MyFastGTI 'MK5 Front Swaybar DIY' (2008)", "Pelican Parts front sway bar bushings article", "GolfMKV APR install troubleshooting thread (2013)", "Golfmk6 install threads (2014, 2015)", "Grassroots Motorsports 034 front bar test (2023)"], "embeds": [], "heroId": "fsb-drop"}$j$::jsonb, updated_at = now() where id = 'sway-front';
update guides set content = $j${"id": "cam-follower", "title": "Cam follower inspection & replacement", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI · 06–08 Jetta 2.0T · 06–08 Passat 2.0T · 07+ Eos · 06–08 A3 · 12–13 Golf R", "category": "Engine", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "30–45 min", "difficulty": 2.5, "cost": "$25–70", "risk": "Pressurized fuel · soft aluminum threads", "why": "This $25 cup wears through, then destroys a $400 fuel pump and a $1,000+ camshaft.", "note": {"text": "Four sources ranged 30 min to 2 hr. The banjo bolt in step 6 is where first-timers lose an hour.", "only": ["stock"]}, "noteAlt": null}, "heroCap": "The pump piston rides on a small steel cup, and the cup rides on the cam. The cup is designed to wear so the cam doesn't. When the cup is gone, the cam does.", "should": {"yesIf": ["You don't know when it was last checked", "10,000+ miles since the last check", {"text": "It's been a full oil change since you last looked", "only": ["upgraded"]}, "Power cuts under boost, stumbles, misfires"], "codes": ["P0087", "P0089", "P1093", "P2293", "P2294"], "notes": ["Early wear has no symptoms. Owners have pulled followers worn through the coating with no check-engine light.", "Read “don't replace it, let VW cover it” somewhere? That was VW's 10-yr/120k-mile extension. For a 2006 car it expired years ago. Replace it.", {"text": "Upgraded pumps push harder on the follower, and owners running them report faster wear. Treat the follower as an every-oil-change check, not a 10–20k item.", "only": ["upgraded"]}], "confidence": {"level": "high", "n": 4, "note": "Symptoms and codes agree across ECS, FCP Euro and multiple forum reports."}}, "parts": [{"tier": "oe", "name": "Cam follower, Genuine VW", "pn": "06D109309C → 06D109309J", "note": "Same part as the INA below, in a VW box", "price": "$45–60", "links": [{"store": "FCP Euro (Genuine)", "url": "https://www.fcpeuro.com/products/audi-volkswagen-fuel-pump-cam-follower-oes-genuine-06d109309c"}]}, {"tier": "oem", "name": "Cam follower, INA", "pn": "06D109309C", "note": "INA makes the factory part. Same follower, half the price", "price": "$25", "links": [{"store": "ECS Tuning (INA)", "url": "https://www.ecstuning.com/b-ina-parts/fuel-pump-cam-follower-06d109309c/06d109309c~ina/"}]}, {"tier": "oem", "name": "Follower kit (follower + o-ring + bolts)", "pn": "06D109309CKT", "note": "Everything in one box", "price": "$45–70", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-assembled-by-ecs-parts/cam-follower-replacement-kit/06d109309ckt/"}]}, {"tier": "oe", "name": "HPFP o-ring", "pn": "in kit", "note": "Old one is usually heat-hardened", "price": "in kit", "links": []}], "tools": [{"name": "T30 Torx on ¼\" drive", "note": "one bolt is too tight for ⅜\"", "price": "$8–15"}, {"name": "M8 triple-square (XZN) stubby bit + 13mm box wrench", "note": "only if you have the banjo bolt (most 2006 cars)", "price": "$10–20"}, {"name": "17mm open-end or flare-nut wrench", "price": "$10"}, {"name": "13mm wrench", "price": "$8"}, {"name": "Torque wrench accurate at 10 Nm", "note": "an inch-pound ¼\" wrench, not a ½\" click wrench", "price": "$40–80"}, {"name": "Small flat screwdriver, rags, safety glasses, assembly lube", "price": "$15"}], "before": ["Engine cold. You're opening the fuel system next to the exhaust side.", "Safety glasses on before step 2. The pump runs at 30–110 bar (435–1,600 psi).", "Anything that falls into the open pump bore falls into your cylinder head. Rag over nearby openings.", "Check which low-pressure fitting you have (bottom of the pump). Metal line held by a small bolt = banjo. Rubber hose on a barbed brass fitting = barb."], "steps": [{"n": 1, "title": "Remove the engine cover", "blocks": [{"t": "text", "b": "Unplug the connector at the back of the cover, release the intake-hose clip, pull the hose off, then grab both sides and wiggle the cover straight up off its grommets."}]}, {"n": 2, "title": "Bleed the fuel pressure", "blocks": [{"t": "text", "b": "Unplug the connector on top of the pump (the pressure regulator). Start the engine and let it run about 10 seconds. It will sputter; that's expected."}, {"t": "text", "b": "Shut it off. Rag over the brass test port on the pump body, remove its black cap, and slowly loosen the port with a 13mm until residual fuel weeps out. Remove it fully; you'll want it out of the way when the pump bolts come out."}, {"t": "warn", "b": "Fuel will still be present. Expect a few tablespoons when the lines come off."}, {"t": "conf", "c": {"level": "community", "n": 3, "note": "Three sources, three variations. All work. None cites the factory procedure."}}]}, {"n": 3, "title": "Unplug and clear the area", "blocks": [{"t": "text", "b": "Unplug the second connector on the side of the pump (pressure sensor; a small flat screwdriver releases the tab). If the PCV/vacuum fitting is in the way, unclip it at its four corners and move it aside. You do not need to remove the main PCV hose."}]}, {"n": 4, "title": "Rag under the pump", "blocks": [{"t": "text", "b": "Fuel will drip onto the head. The rag also catches anything you drop."}]}, {"n": 5, "title": "Loosen the high-pressure hard line", "blocks": [{"t": "text", "b": "17mm on the collar nut where the metal line meets the pump. Slide the collar back. Don't bend or lever the line; the fittings are brass."}]}, {"n": 6, "title": "Remove the low-pressure fitting", "timeSink": true, "blocks": [{"t": "fork", "q": "Which fitting do you have?", "v": [{"label": "Banjo bolt", "when": "Most 2006 cars", "blocks": [{"t": "text", "b": "Seat the stubby M8 triple-square in the bolt head and turn it with a box wrench on the bit's shank. Tape around the bit keeps it in the wrench. Fine threads into brass: go slow."}, {"t": "ill", "id": "banjo", "cap": "Stubby bit in the bolt head, wrench on the bit. If the bit walks out of the head, stop and re-seat it; a rounded head here is a bad day."}, {"t": "embed", "id": "wBCHQCF6si4", "title": "See the banjo bolt", "note": "AskDAP answers a 2006 GLI owner asking how to get rid of this fitting"}]}, {"label": "Barbed fitting", "when": "2008+, or converted", "blocks": [{"t": "text", "b": "Squeeze the spring clamp and slide the rubber hose off the barb."}]}]}, {"t": "note", "b": "This is the step that turns a 45-minute job into a 2-hour one. Several owners eventually convert to the barbed style ($50–250 in parts) so they never fight this bolt again."}]}, {"n": 7, "title": "Remove the three T30 pump bolts", "blocks": [{"t": "text", "b": "With the test port already out, the lowest bolt is reachable. Use ¼\" drive for the tight one. Loosen all three evenly."}]}, {"n": 8, "title": "Pull the pump", "blocks": [{"t": "text", "b": "Wiggle it straight out. If the o-ring has hardened it may stick; tap the pump body gently with a plastic mallet. Do not pry against the head. Set it down piston-end up."}, {"t": "warn", "b": "The cam is now exposed. Nothing goes in that hole except your fingertip and the new follower."}]}, {"n": 9, "title": "Remove the old follower", "blocks": [{"t": "text", "b": "Reach in with a fingertip and slide the cup out. Look at it now (see Reading your old follower below), then look at the cam lobe with a light and mirror, and at the end of the pump piston."}, {"t": "note", "b": "With a high-flow pump, don't be surprised to find the coating worn through at half the mileage a stock car would show it. That's the pump doing its job, not a defective follower.", "only": ["upgraded"]}]}, {"n": 10, "title": "Install the new follower", "blocks": [{"t": "text", "b": "Oil the outside of the cup and put a generous smear of assembly lube on its face. Slide it into the bore, open side toward the pump. A dab of lube on the cam lobe is cheap insurance against a dry start."}]}, {"n": 11, "title": "New o-ring on the pump", "blocks": [{"t": "text", "b": "Pull the old o-ring from the pump's groove, clean the groove, fit the new one. Wipe the pump's mating face and the bore area on the head."}]}, {"n": 12, "title": "Install the pump", "caution": true, "blocks": [{"t": "note", "b": "Upgraded pumps use the same three T30 bolts and the same 10 Nm. Some kits ship longer bolts with a spacer; if yours did, use the kit's bolts and its torque sheet.", "only": ["upgraded"]}, {"t": "text", "b": "Check the cam lobe. If its peak is pointing at the follower, the pump needs a lot of force to seat and the bolts start under load. You want the flat flank. If it's on the nose, either push the pump down firmly and squarely while starting the bolts, or bump the crank pulley slightly to rotate it off."}, {"t": "ill", "id": "lobe", "cap": "Left is what you want. Right works, but you're fighting the spring and it's easy to cross-thread a bolt while pushing."}, {"t": "text", "b": "Press the pump squarely into the bore so the spring compresses, then start all three bolts by hand. Tighten them alternately, a little at a time, so the pump draws down evenly."}, {"t": "torque", "label": "HPFP mounting bolts (T30 ×3)", "nm": 10, "c": {"level": "high", "n": 5, "note": "10 Nm / 7–7.5 lb-ft agrees across ECS, FCP Euro, MyFastGTI and three VWVortex threads."}}, {"t": "warn", "b": "10 Nm is barely more than a firm hand-tightening. These bolts thread into soft aluminum. Over-torque strips the head, and now you're helicoiling a cylinder head with a fuel pump hanging off it. No torque wrench that reads 10 Nm? Stop and get one."}]}, {"n": 13, "title": "Reinstall the low-pressure fitting", "blocks": [{"t": "fork", "q": "Which fitting do you have?", "v": [{"label": "Banjo bolt", "when": "Most 2006 cars", "blocks": [{"t": "text", "b": "Bolt and brass threads spotless and burr-free. Thread it in by hand at least 4–5 full turns before touching a wrench. If it doesn't spin freely, back it out and start again: it's cross-threaded. No sealing washers on this fitting."}, {"t": "torque", "label": "Banjo bolt", "nm": 17, "c": {"level": "single", "n": 1, "note": "One source for this value. Thread cleanliness matters more than the number."}}]}, {"label": "Barbed fitting", "when": "2008+, or converted", "blocks": [{"t": "text", "b": "Push the hose fully onto the barb and reseat the spring clamp."}]}]}]}, {"n": 14, "title": "Reinstall the high-pressure hard line", "blocks": [{"t": "text", "b": "Thread the 17mm collar on and tighten. In practice: snug with a wrench until it won't weep."}, {"t": "torque", "label": "Hard-line collar nut (17mm)", "nm": 25, "alt": [27], "c": {"level": "varies", "n": 2, "note": "25 Nm vs 27 Nm. Neither is from a factory manual."}}]}, {"n": 15, "title": "Test port, connectors, hoses", "blocks": [{"t": "text", "b": "Reinstall the brass test port (13mm, snug) and its cap. Reconnect both connectors and any vacuum/PCV fitting you moved."}]}, {"n": 16, "title": "Start and check for leaks", "blocks": [{"t": "text", "b": "It may stumble for a few seconds while pressure builds. Look and smell for fuel at the banjo, the hard-line collar and the test port. Anything weeps: shut off and re-seat that fitting. Clear codes."}]}, {"n": 17, "title": "Engine cover back on", "blocks": [{"t": "text", "b": "Reverse step 1. Drive it. A stumble that persists beyond a few minutes means recheck the connectors."}]}], "check": {"tab": "Read the wear", "title": "Reading your old follower", "illId": "wear", "illCap": "Face-on, as you'll see it in your hand. B is where most people find theirs.", "rows": [{"see": "Black coating intact, maybe faint scuffing", "means": "Normal. The anti-wear coating is doing its job.", "do": "Reinstall or replace (it's cheap). Check again in 10–20k."}, {"see": "Silver showing through the black in the center", "means": "Coating gone; base metal wearing. Where most followers are found at 50–80k.", "do": "Replace. Check the cam lobe: smooth and shiny means you're fine."}, {"see": "Concave, worn through, or in pieces", "means": "Late-stage failure. The pump piston has been riding the cam.", "do": "Replace, and inspect cam lobe + pump piston for scoring. Scored lobe = camshaft. Galled piston = pump. Change the oil."}], "c": {"level": "medium", "n": 4, "note": "Rubric consistent across ECS, FCP Euro and owner photos on two forums."}}, "aftercare": ["No factory inspection interval exists. VW's schedule never listed it.", {"text": "Community consensus: inspect every 10,000–20,000 miles (every oil change or every other).", "only": ["stock"]}, {"text": "Community consensus for upgraded pumps: inspect every oil change, and keep a spare follower in the glovebox. They're $25.", "only": ["upgraded"]}, "Second time is a 30–45 minute job. Consider converting the banjo to the barbed fitting.", "Keep your oil level up. Whatever the root cause, a dry follower dies faster."], "disagreements": [{"topic": "Does the banjo bolt exist?", "pos": "FCP Euro's guide never mentions it; three other sources spend the most words on it.", "call": "Their car had the later fitting. 2006 cars: assume banjo."}, {"topic": "Hard-line torque", "pos": "25 Nm vs 27 Nm.", "call": "Show the range, flag as non-factory."}, {"topic": "Inspection interval", "pos": "“Every 10k” vs “every 10k is overkill” vs “not a service item.”", "call": "10–20k; 10k if tuned."}, {"topic": "Replace, or wait for warranty?", "pos": "A 2013 thread said wait and let VW pay.", "call": "Extension expired for 2006 cars. Replace."}, {"topic": "Root cause", "pos": "Soft cam vs low-ZDDP US oil vs bad design.", "call": "VW revised the cam three times and extended the warranty; that's what's verifiable. Oil theory unproven."}, {"topic": "Triple-square size", "pos": "M8 (three sources) vs M5 (one).", "call": "M8."}], "sources": ["FCP Euro DIY (2022, Humble Mechanic)", "ECS Tuning blog DIY (2017)", "MyFastGTI DIY thread (2010–14)", "VWVortex: torque spec, stripped threads, early replacement, INA roller, “stop replacing”", "DAP: cam revisions, banjo conversion", "Audi-Sport.net banjo cutover", "markFive GTI warranty letters", "Audi TT Forum owner reports", "ECS product listings"], "embeds": [{"id": "5CD6obyhZmg", "note": "Humble Mechanic for FCP Euro, 2022. His car has the later hose fitting, so his step 3 skips the banjo bolt you probably have."}, {"id": "wBCHQCF6si4", "note": "AskDAP — the banjo bolt question"}], "variants": {"question": "Which fuel pump is on your car?", "hint": "The high-pressure pump sits on top of the engine at the back. A factory or OEM replacement pump is black with a VW/Hitachi marking. Upgraded pumps (APR, Autotech, and others) usually came with a tune and often have a machined or anodized top.", "options": [{"id": "stock", "label": "Stock or OEM replacement", "when": "Never changed, or replaced with a factory-style pump"}, {"id": "upgraded", "label": "Upgraded high-flow pump", "when": "APR, Autotech or similar, typically on a Stage 2+ tune"}]}, "aftermarket": [{"name": "Coated 'upgraded' followers", "note": "A few specialists sell followers with a thicker or different anti-wear coating. Forum reports are mixed and the factory part is cheap, so most owners stay OEM.", "price": "$60–120", "signal": "Community verdict: skip, buy INA", "links": []}, {"name": "Roller-follower conversion (TSI-style)", "note": "Replaces the flat follower with the roller design VW used on the later TSI. Involved install, documented on VWVortex; for people who want the wear problem gone for good.", "price": "$150+", "signal": "Enthusiast option", "links": []}], "lifespan": {"title": "When to expect it", "headline": [{"text": "Coating typically worn through between 50,000 and 80,000 miles", "only": ["stock"]}, {"text": "With a high-flow pump, expect it in half that: 25,000 to 40,000 miles", "only": ["upgraded"]}], "earliest": "Earliest failures reported around 15,000 miles on early (2006) camshafts", "detail": "Owner photos cluster around 65–70k for a follower that's silver in the middle but still flat. Past 85k on an unchecked car, worn-through and concave followers become common.", "factors": ["Upgraded HPFP or Stage 2+ tune", "Early 'A' revision camshaft (2006)", "Low oil level", "Never inspected"], "inspect": [{"text": "Inspect every 10,000–20,000 miles", "only": ["stock"]}, {"text": "Inspect every oil change", "only": ["upgraded"]}], "confidence": {"level": "community", "n": 9, "note": "Nine owner reports with photos across three forums, plus two vendor notes. No factory interval exists."}}, "heroId": "hero"}$j$::jsonb, updated_at = now() where id = 'cam-follower';
